import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.URL;

import static org.junit.Assert.*;

public class UrlBuilderTest {

    @Test
    public void urlBuilderConstructorTest() {
        URL testUrl = new URL("https://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(testUrl);

        assertNotNull(urlBuilder);
    }

    @Test(expected = IllegalArgumentException.class)
    public void urlBuilderConstructorNullTest() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
    }

    @Test
    public void buildValidUrlTest() {
        URL testUrl = new URL("https://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(testUrl);
        URL resultUrl = urlBuilder.build();

        assertNotNull(resultUrl);
        assertEquals("https://www.example.com", resultUrl.toString());
    }

    @Test(expected = MalformedURLException.class)
    public void buildInvalidUrlTest() {
        URL testUrl = new URL("invalidUrl");
        UrlBuilder urlBuilder = new UrlBuilder(testUrl);
        URL resultUrl = urlBuilder.build();
    }

    @Test
    public void appendKeyValValidTest() throws UnsupportedEncodingException {
        URL testUrl = new URL("https://www.example.com");
        Connection.KeyVal keyVal = Connection.KeyVal.create("key", "value");

        UrlBuilder urlBuilder = new UrlBuilder(testUrl);
        urlBuilder.appendKeyVal(keyVal);

        URL resultUrl = urlBuilder.build();

        assertNotNull(resultUrl);
        assertEquals("https://www.example.com?key=value", resultUrl.toString());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValInvalidTest() throws UnsupportedEncodingException {
        URL testUrl = new URL("https://www.example.com");
        Connection.KeyVal keyVal = Connection.KeyVal.create("invalidKey", "invalidValue");

        UrlBuilder urlBuilder = new UrlBuilder(testUrl);
        urlBuilder.appendKeyVal(keyVal);
    }
}
